const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Footer, TabStopType, TabStopPosition,
  ExternalHyperlink
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

const accent = "1E5A8C";
const accentLight = "D5E8F8";
const gray = "F5F5F5";
const darkGray = "444444";

function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function h3(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(text)] });
}
function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new TextRun({ text, ...opts })]
  });
}
function spacer() {
  return new Paragraph({ spacing: { after: 80 }, children: [] });
}
function bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    spacing: { after: 100 },
    children: [new TextRun(text)]
  });
}
function inlineCode(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: "C0392B" });
}
function pMixed(children) {
  return new Paragraph({ spacing: { after: 160 }, children });
}

function sectionDivider(label) {
  return new Paragraph({
    spacing: { before: 320, after: 80 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: accent, space: 4 } },
    children: [new TextRun({ text: label, bold: true, size: 28, color: accent })]
  });
}

function statusTable(rows) {
  const colWidths = [2800, 3000, 3560];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          ["Requirement", accentLight],
          ["Decision", accentLight],
          ["Rationale", accentLight],
        ].map(([txt, fill], i) => new TableCell({
          borders,
          width: { size: colWidths[i], type: WidthType.DXA },
          shading: { fill, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: txt, bold: true, size: 20 })] })]
        }))
      }),
      ...rows.map(([req, dec, rat], idx) => new TableRow({
        children: [req, dec, rat].map((txt, i) => new TableCell({
          borders,
          width: { size: colWidths[i], type: WidthType.DXA },
          shading: { fill: idx % 2 === 0 ? "FFFFFF" : gray, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: txt, size: 20 })] })]
        }))
      }))
    ]
  });
}

function twoColTable(rows, colWidths = [3000, 6360]) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: rows.map(([left, right, header], idx) => new TableRow({
      tableHeader: !!header,
      children: [left, right].map((txt, i) => new TableCell({
        borders,
        width: { size: colWidths[i], type: WidthType.DXA },
        shading: { fill: header ? accentLight : (idx % 2 === 0 ? "FFFFFF" : gray), type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: txt, bold: !!header, size: 20 })] })]
      }))
    }))
  });
}

function quotaTable() {
  const cols = [2200, 1720, 1720, 1720, 2000];
  const headers = ["Attribute", "Default tier", "Standard tier", "Power tier", "Notes"];
  const data = [
    ["Assignment", "Automatic", "Operator assigned", "Operator assigned", "Default on first deploy"],
    ["Max apps", "2", "10", "25", "Per team"],
    ["CPU per app", "0.5 cores", "1 core", "4 cores", "Kubernetes limit"],
    ["Memory per app", "512 MB", "1 GB", "4 GB", "Kubernetes limit"],
    ["Storage", "10 GB", "100 GB", "500 GB", "GCS + Cloud SQL combined"],
    ["Max cost exposure", "~$15/mo", "~$80/mo", "~$300/mo", "Estimated ceiling"],
    ["Hibernate after", "24 hrs idle", "48 hrs idle", "72 hrs idle", "Configurable per app"],
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: cols,
    rows: [
      new TableRow({
        tableHeader: true,
        children: headers.map((h, i) => new TableCell({
          borders,
          width: { size: cols[i], type: WidthType.DXA },
          shading: { fill: accentLight, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: h, bold: true, size: 20 })] })]
        }))
      }),
      ...data.map((row, idx) => new TableRow({
        children: row.map((cell, i) => new TableCell({
          borders,
          width: { size: cols[i], type: WidthType.DXA },
          shading: { fill: idx % 2 === 0 ? "FFFFFF" : gray, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: cell, size: 20 })] })]
        }))
      }))
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [
          { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } } },
          { level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 1080, hanging: 360 } } } },
        ]
      }
    ]
  },
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: "222222" } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Arial", color: accent },
        paragraph: { spacing: { before: 400, after: 200 }, outlineLevel: 0,
          border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: accent, space: 4 } } }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: darkGray },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 1 }
      },
      {
        id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: "555555" },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 2 }
      },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    footers: {
      default: new Footer({
        children: [new Paragraph({
          tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
          children: [
            new TextRun({ text: "Internal — Non-Production PaaS Design Spec  ", size: 18, color: "888888" }),
            new TextRun({ children: [new PageNumber()], size: 18, color: "888888" }),
          ]
        })]
      })
    },
    children: [

      // ── Cover ──────────────────────────────────────────────────────────────
      new Paragraph({ spacing: { before: 1440, after: 80 }, children: [
        new TextRun({ text: "Non-Production PaaS", bold: true, size: 56, font: "Arial", color: accent })
      ]}),
      new Paragraph({ spacing: { after: 80 }, children: [
        new TextRun({ text: "Design & Architecture Specification", size: 36, font: "Arial", color: darkGray })
      ]}),
      new Paragraph({ spacing: { after: 480 }, children: [
        new TextRun({ text: "Version 0.1  ·  May 2026  ·  Draft", size: 22, color: "888888" })
      ]}),
      new Paragraph({
        border: { left: { style: BorderStyle.SINGLE, size: 24, color: accent, space: 12 } },
        indent: { left: 360 },
        spacing: { after: 600 },
        children: [
          new TextRun({ text: "A self-hosted platform-as-a-service for hosting non-production applications (demos, experiments) in a dedicated GCP project, designed for low operator maintenance with strong cost controls and a Heroku-style developer experience.", size: 22, italics: true, color: "444444" })
        ]
      }),

      // ── 1. Goals & Non-goals ───────────────────────────────────────────────
      h1("1  Goals and non-goals"),
      h2("Goals"),
      bullet("Let developers deploy containerised apps with nothing more than a git push"),
      bullet("Support HTTP servers, background workers, and scheduled jobs"),
      bullet("Provide managed persistence: blob storage, databases, and queues"),
      bullet("Enforce cost caps automatically; require no manual intervention for routine use"),
      bullet("Detect and hibernate idle apps; wake them transparently on next request"),
      bullet("Manage DNS and HTTPS automatically under an operator-controlled domain"),
      bullet("Keep apps unreachable from the public internet when required"),
      bullet("Allow ownership transfer of apps between teams without downtime"),
      bullet("Require part-time attention from a single, rotating operator"),
      spacer(),
      h2("Non-goals"),
      bullet("Production workloads — this platform has no SLA"),
      bullet("Multi-region or high-availability deployments"),
      bullet("Supporting workloads that require GPUs or specialised hardware"),
      bullet("Replacing an internal developer portal (Backstage, etc.)"),
      bullet("Serving as a general-purpose CI/CD platform"),
      spacer(),

      // ── 2. Personas ────────────────────────────────────────────────────────
      h1("2  Personas"),
      h2("Designer / implementer"),
      p("Builds and evolves the platform itself. Comfortable with Kubernetes internals, Terraform, Helm, and GCP. Interacts with the full stack. This role is not the operator; complexity is acceptable here because it is absorbed once during construction and rarely during maintenance."),
      h2("Operator"),
      p("Manages the running platform on a part-time basis. The role may rotate. The operator has no expectation of Kubernetes or GCP knowledge. Their entire workflow is through a purpose-built admin UI. Routine tasks should take minutes, not hours."),
      p("The operator's task surface is deliberately narrow:"),
      bullet("Review new teams that have auto-registered"),
      bullet("Promote teams to higher quota tiers on request"),
      bullet("Transfer app ownership when a team is dissolved"),
      bullet("Glance at cost and health dashboards"),
      bullet("Act on alerts (failed deploys, budget thresholds, expiring certs)"),
      h2("Developer / app owner"),
      p("A member of the GitHub organisation. Deploys and operates apps on behalf of their team. Has no cloud or Kubernetes knowledge required. Their entire interface is a git repository and a paas.yaml manifest in its root."),
      spacer(),

      // ── 3. Architecture overview ───────────────────────────────────────────
      h1("3  Architecture overview"),
      p("The platform is built on GKE (Google Kubernetes Engine) running in a dedicated non-production GCP project. Kubernetes complexity is fully hidden from both operators and developers; only the designer interacts with it directly."),
      p("The architecture is composed of six layers:"),
      twoColTable([
        ["Layer", "Responsibility", true],
        ["Developer experience", "git push triggers a GitHub Actions workflow that builds a container, pushes it to Artifact Registry, and calls the PaaS deploy API"],
        ["Control plane", "Argo CD (GitOps reconciliation), KEDA (autoscaling and hibernation), cert-manager, external-dns"],
        ["GKE runtime", "One Kubernetes namespace per app; Deployments, CronJobs, ResourceQuotas, LimitRanges"],
        ["Persistence", "GCS buckets, Cloud SQL instances, Cloud Pub/Sub topics — all managed, one per app"],
        ["Network / DNS / TLS", "GKE Gateway API, VPC-native networking, internal load balancer, Cloud DNS, Let\u2019s Encrypt"],
        ["Identity / cost", "GitHub OIDC tokens, Workload Identity Federation, GCP budget alerts, Namespace ResourceQuota"],
      ]),
      spacer(),

      // ── 4. Security model ──────────────────────────────────────────────────
      h1("4  Security model"),
      h2("Core principle: GitHub calls the PaaS, not the other way around"),
      p("An earlier design considered the PaaS polling the GitHub API to sync team membership. This was rejected because it required the PaaS to hold a long-lived GitHub token with org-level read access — a token that, if leaked, could enumerate all org members, teams, and repositories."),
      p("The adopted model inverts the relationship: GitHub Actions calls the PaaS API and presents a short-lived OIDC token as proof of identity. The PaaS never holds a GitHub credential of any kind."),
      h2("GitHub OIDC token flow"),
      bullet("GitHub Actions generates a short-lived JWT (5-minute TTL) signed by GitHub\u2019s private key"),
      bullet("The token contains verifiable claims: repository, git ref, workflow SHA, and the triggering actor\u2019s team membership"),
      bullet("The PaaS validates the token signature against GitHub\u2019s public JWKS endpoint (read-only, no credential required)"),
      bullet("The PaaS extracts the team claim and uses it for authorisation"),
      spacer(),
      h2("What the PaaS holds vs. what it never holds"),
      twoColTable([
        ["PaaS holds", "PaaS never holds", true],
        ["GitHub\u2019s public JWKS URL (read-only)", "GitHub PAT or OAuth token"],
        ["Its own internal team and app records", "Org membership read access"],
        ["GCP service account keys (via Workload Identity)", "Any credential that can enumerate the GitHub org"],
      ]),
      spacer(),
      h2("Blast radius if the PaaS is compromised"),
      p("An attacker who fully compromises the PaaS can: deploy or delete apps on the platform, exhaust quota, and access data stored in platform-managed persistence. They cannot: enumerate the GitHub organisation, read source code, impersonate users outside the platform, or access other GCP projects."),
      spacer(),

      // ── 5. Ownership model ─────────────────────────────────────────────────
      h1("5  Ownership model"),
      h2("GitHub teams as owners"),
      p("Apps are owned by GitHub teams, not individual users. This makes ownership stable across membership churn: when someone joins or leaves a team, access to that team\u2019s apps follows automatically without any operator action."),
      pMixed([new TextRun("The "), inlineCode("owner"), new TextRun(" field in "), inlineCode("paas.yaml"), new TextRun(" is a team slug in the form "), inlineCode("org/team-name"), new TextRun(".")]),
      spacer(),
      h2("Membership lifecycle"),
      twoColTable([
        ["Event", "Platform behaviour", true],
        ["Member joins a team", "Automatically gains deploy access to that team\u2019s apps on next deploy attempt. No operator action."],
        ["Member leaves the org", "Access revoked on the next OIDC token validation. Apps remain under team ownership."],
        ["Team dissolved", "Operator transfers app ownership to another team via the admin UI. This is the only event requiring operator action."],
      ]),
      spacer(),

      // ── 6. Team & quota model ──────────────────────────────────────────────
      h1("6  Team and quota model"),
      h2("Automatic team onboarding"),
      p("When the PaaS receives the first deploy request from a previously unknown GitHub team, it automatically creates a team record and assigns the default quota tier. The deploy succeeds immediately. The operator receives a digest notification but is not in the critical path."),
      p("This achieves the low-maintenance property of fully automatic onboarding while bounding cost exposure through the default tier limits."),
      spacer(),
      h2("Quota tiers"),
      quotaTable(),
      spacer(),
      p("The default tier is intentionally sized so that a team can fully validate a working application without hitting resource constraints, but cannot consume meaningful budget without operator awareness."),
      h2("Quota enforcement"),
      bullet("Kubernetes ResourceQuota and LimitRange enforce CPU and memory at the namespace level"),
      bullet("When a team hits their app count limit, the deploy API returns a clear error message directing them to contact the operator"),
      bullet("Budget alerts fire at 80% and 100% of tier ceiling; the operator is notified but no automatic action is taken"),
      bullet("Operator can promote a team\u2019s tier in the admin UI in under 30 seconds"),
      spacer(),

      // ── 7. Developer interface ─────────────────────────────────────────────
      h1("7  Developer interface"),
      h2("paas.yaml"),
      p("The entire configuration surface for a developer is a paas.yaml file in the root of their repository. No Kubernetes knowledge is required."),
      new Paragraph({
        spacing: { after: 160 },
        children: [new TextRun({
          text: [
            "name: my-demo-app",
            "owner: org/team-alpha       # GitHub team slug",
            "type: http                  # http | worker | cronjob",
            "schedule: \"0 9 * * 1-5\"   # required if type: cronjob",
            "tier: small                 # small | medium | large (within team quota)",
            "private: true               # internal-only ingress if true",
            "persistence:",
            "  database: postgres        # omit if not needed",
            "  storage: true",
            "  queue: true",
          ].join('\n'),
          font: "Courier New", size: 18, color: "222222"
        })]
      }),
      h2("Deploy flow"),
      bullet("Developer pushes to the default branch of their repository"),
      bullet("GitHub Actions workflow runs: lint, test, build container, push to Artifact Registry"),
      bullet("Workflow calls the PaaS deploy API with the new image digest and the OIDC token"),
      bullet("PaaS validates the token, checks team ownership and quota, updates the app\u2019s Kubernetes manifest"),
      bullet("Argo CD detects the manifest change and reconciles the cluster state"),
      bullet("The app is live within seconds of Argo CD sync"),
      spacer(),

      // ── 8. Operator interface ──────────────────────────────────────────────
      h1("8  Operator interface"),
      p("The operator interacts exclusively with a purpose-built web admin UI. The UI is desktop-only. No terminal, kubectl, or GCP console access is required for routine operations."),
      h2("Admin UI task surface"),
      twoColTable([
        ["Area", "Actions available", true],
        ["App management", "View all apps with owner team, status, and cost; hibernate or wake an app; delete an app; transfer ownership to another team; adjust per-app resource tier"],
        ["Team management", "View all registered teams; view per-team app count and cost; promote or demote quota tier; suspend a team"],
        ["Cost and quotas", "View total and per-team spend; set budget alert thresholds; view apps approaching quota ceiling; view hibernate candidates"],
        ["Platform health", "Cluster status summary; failed deploy log; certificate and DNS alerts; upgrade notifications from the designer"],
      ]),
      spacer(),
      h2("Routine operator cadence"),
      p("Expected time investment is a few hours per month, not per week. The platform is designed so that no operator action is required for normal day-to-day developer activity."),
      bullet("Weekly: glance at cost dashboard and new team digest"),
      bullet("On request: promote a team\u2019s quota tier (triggered by developer reaching their limit)"),
      bullet("On offboarding: transfer app ownership when a team is dissolved"),
      bullet("On alert: investigate and resolve cert, DNS, or budget alerts"),
      spacer(),

      // ── 9. Hibernation ─────────────────────────────────────────────────────
      h1("9  Hibernation"),
      p("Apps that receive no traffic for their configured idle threshold are automatically scaled to zero replicas by KEDA. Persistence (database, storage, queue) is retained. The app is woken transparently when the next HTTP request arrives, via the KEDA HTTP add-on which holds the request while the pod starts."),
      twoColTable([
        ["Property", "Behaviour", true],
        ["Idle detection", "KEDA monitors HTTP request rate; zero requests for idle threshold triggers scale-to-zero"],
        ["Wake-on-request", "KEDA HTTP add-on intercepts the first request and holds it while the pod initialises"],
        ["Cold start time", "Typically 5\u201315 seconds depending on container image size"],
        ["Persistence during hibernation", "All data retained; no cleanup of database or storage"],
        ["Worker hibernation", "Workers scale to zero when their queue is empty (KEDA queue scaler)"],
        ["CronJob hibernation", "CronJobs are suspended when the app is hibernated; schedule resumes on wake"],
      ]),
      spacer(),

      // ── 10. Decisions log ──────────────────────────────────────────────────
      h1("10  Key decisions log"),
      p("This section records the significant design decisions made and the reasoning behind them. It should be updated as the design evolves."),
      spacer(),
      statusTable([
        ["Infrastructure", "GKE (full Kubernetes control plane)", "Scale target (50+ users, 500+ apps) rules out simpler managed options. Designer is comfortable with K8s complexity."],
        ["GitOps engine", "Argo CD", "Mature, well-supported, integrates cleanly with Kubernetes manifests. Pull-based model means the cluster is always the source of truth."],
        ["Autoscale / hibernate", "KEDA + KEDA HTTP add-on", "Single tool handles both queue-driven worker scaling and HTTP-driven hibernation. Scale-to-zero is native."],
        ["GitHub integration", "Push model (GitHub calls PaaS)", "Pull model (PaaS polls GitHub) requires long-lived GitHub token with org-read scope. Rejected on security grounds. OIDC tokens are short-lived and carry no org-level access."],
        ["App ownership", "GitHub teams (not individuals)", "Teams are stable across membership churn. Individual ownership requires operator action on every departure."],
        ["Team onboarding", "Automatic with default quota", "Fully manual onboarding is high operator burden. Automatic onboarding with a low default quota achieves low maintenance while bounding cost exposure."],
        ["Quota tiers", "Three tiers: default, standard, power", "Coarse tiers are easier to explain and administer than per-app limits. Default tier auto-assigned; upper tiers require operator action."],
        ["Operator tooling", "Custom admin UI (web)", "Operator may rotate and has no K8s/GCP knowledge. kubectl and GCP console are not acceptable operator interfaces."],
        ["Persistence", "GCS, Cloud SQL, Cloud Pub/Sub", "Fully managed GCP services; no in-cluster databases to operate. One resource per app for isolation."],
        ["DNS / TLS", "external-dns + cert-manager + Let\u2019s Encrypt", "Fully automated; zero operator involvement in cert renewal or DNS record management."],
      ]),
      spacer(),

      // ── 11. Open questions ─────────────────────────────────────────────────
      h1("11  Open questions"),
      p("The following questions are unresolved and should be addressed before implementation of the relevant component begins."),
      bullet("What is the operator\u2019s notification channel? (Slack, email, or both?)"),
      bullet("What domain will the platform manage? (e.g. apps.internal.example.com)"),
      bullet("Should the default idle threshold be configurable per-app in paas.yaml, or set platform-wide by the operator?"),
      bullet("How should database credentials be vended to apps? (Kubernetes secrets, GCP Secret Manager, or both?)"),
      bullet("What is the GCP project naming convention and budget ceiling for the platform as a whole?"),
      bullet("Should the admin UI require authentication via GitHub OAuth (tying operator identity to GitHub org membership), or a standalone credential?"),
      bullet("What is the process for the designer to push platform upgrades (GKE versions, Helm chart updates) with minimal operator involvement?"),
      spacer(),

      // ── 12. Iterative build plan ───────────────────────────────────────────
      h1("12  Iterative build plan"),
      p("The platform will be built incrementally. Each layer is independently useful and testable before the next is started."),
      twoColTable([
        ["Phase", "Scope", true],
        ["1 \u2014 Foundation", "GCP project, GKE cluster, Artifact Registry, VPC, Terraform baseline"],
        ["2 \u2014 GitOps core", "Argo CD installation, namespace-per-app scaffolding, basic paas.yaml manifest rendering"],
        ["3 \u2014 Deploy API", "PaaS API service, GitHub OIDC validation, team auto-registration, quota enforcement"],
        ["4 \u2014 Networking", "GKE Gateway API, internal/external ingress, cert-manager, external-dns, custom domain"],
        ["5 \u2014 Persistence", "GCS bucket provisioning, Cloud SQL vending, Pub/Sub topic creation, secret injection"],
        ["6 \u2014 Hibernation", "KEDA installation, HTTP add-on, idle detection, scale-to-zero, wake-on-request"],
        ["7 \u2014 Admin UI", "Operator web UI: app list, team management, quota promotion, cost dashboard"],
        ["8 \u2014 Hardening", "Budget alerts, audit logging, disaster recovery runbook, operator handover documentation"],
      ]),
      spacer(),
      p("Each phase will produce a working, reviewable increment. Design decisions specific to a phase will be captured in addenda to this document before that phase begins."),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/mnt/user-data/outputs/paas-design-spec.docx', buf);
  console.log('done');
});

