{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Footer, TabStopType, TabStopPosition,
  ExternalHyperlink
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

const accent = "1E5A8C";
const accentLight = "D5E8F8";
const gray = "F5F5F5";
const darkGray = "444444";

function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function h3(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(text)] });
}
function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new TextRun({ text, ...opts })]
  });
}
function spacer() {
  return new Paragraph({ spacing: { after: 80 }, children: [] });
}
function bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    spacing: { after: 100 },
    children: [new TextRun(text)]
  });
}
function inlineCode(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: "C0392B" });
}
function pMixed(children) {
  return new Paragraph({ spacing: { after: 160 }, children });
}

function sectionDivider(label) {
  return new Paragraph({
    spacing: { before: 320, after: 80 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: accent, space: 4 } },
    children: [new TextRun({ text: label, bold: true, size: 28, color: accent })]
  });
}

function statusTable(rows) {
  const colWidths = [2800, 3000, 3560];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          ["Requirement", accentLight],
          ["Decision", accentLight],
          ["Rationale", accentLight],
        ].map(([txt, fill], i) => new TableCell({
          borders,
          width: { size: colWidths[i], type: WidthType.DXA },
          shading: { fill, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: txt, bold: true, size: 20 })] })]
        }))
      }),
      ...rows.map(([req, dec, rat], idx) => new TableRow({
        children: [req, dec, rat].map((txt, i) => new TableCell({
          borders,
          width: { size: colWidths[i], type: WidthType.DXA },
          shading: { fill: idx % 2 === 0 ? "FFFFFF" : gray, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: txt, size: 20 })] })]
        }))
      }))
    ]
  });
}

function twoColTable(rows, colWidths = [3000, 6360]) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: rows.map(([left, right, header], idx) => new TableRow({
      tableHeader: !!header,
      children: [left, right].map((txt, i) => new TableCell({
        borders,
        width: { size: colWidths[i], type: WidthType.DXA },
        shading: { fill: header ? accentLight : (idx % 2 === 0 ? "FFFFFF" : gray), type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: txt, bold: !!header, size: 20 })] })]
      }))
    }))
  });
}

function quotaTable() {
  const cols = [2200, 1720, 1720, 1720, 2000];
  const headers = ["Attribute", "Default tier", "Standard tier", "Power tier", "Notes"];
  const data = [
    ["Assignment", "Automatic", "Operator assigned", "Operator assigned", "Default on first deploy"],
    ["Max apps", "2", "10", "25", "Per team"],
    ["CPU per app", "0.5 cores", "1 core", "4 cores", "Kubernetes limit"],
    ["Memory per app", "512 MB", "1 GB", "4 GB", "Kubernetes limit"],
    ["Storage", "10 GB", "100 GB", "500 GB", "GCS + Cloud SQL combined"],
    ["Max cost exposure", "~$15/mo", "~$80/mo", "~$300/mo", "Estimated ceiling"],
    ["Hibernate after", "24 hrs idle", "48 hrs idle", "72 hrs idle", "Configurable per app"],
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: cols,
    rows: [
      new TableRow({
        tableHeader: true,
        children: headers.map((h, i) => new TableCell({
          borders,
          width: { size: cols[i], type: WidthType.DXA },
          shading: { fill: accentLight, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: h, bold: true, size: 20 })] })]
        }))
      }),
      ...data.map((row, idx) => new TableRow({
        children: row.map((cell, i) => new TableCell({
          borders,
          width: { size: cols[i], type: WidthType.DXA },
          shading: { fill: idx % 2 === 0 ? "FFFFFF" : gray, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: cell, size: 20 })] })]
        }))
      }))
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [
          { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } } },
          { level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 1080, hanging: 360 } } } },
        ]
      }
    ]
  },
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: "222222" } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Arial", color: accent },
        paragraph: { spacing: { before: 400, after: 200 }, outlineLevel: 0,
          border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: accent, space: 4 } } }
      },
      {
